
from typing import TypedDict, NotRequired

from schemas.priority import EmailPriority
from agents.action_agent import ActionResult
from agents.summary_agent import SummaryResult


class EmailState(TypedDict):
    # Original Gmail message
    email_id: str
    thread_id: str
    received_at_ms: int
    sender: str
    subject: str
    body: str

    # Personalization
    user_priorities: str

    # Results generated by agents
    priority_result: NotRequired[EmailPriority]
    action_result: NotRequired[ActionResult]
    summary_result: NotRequired[SummaryResult]

    # Final dashboard placement
    dashboard_group: NotRequired[str]

    # Optional error information
    error: NotRequired[str]
